<script setup lang="ts">import { ref } from 'vue'; import { CheckCircle2, ShieldAlert, ExternalLink } from 'lucide-vue-next'; import { checklist, toggleCheck } from '../composables'; const items=[['mfa','Ative a autenticação multifator'],['updates','Mantenha aplicativos e sistema atualizados'],['unique','Use senhas únicas para cada conta'],['permissions','Revise permissões dos aplicativos'],['recovery','Configure formas seguras de recuperação'],['links','Verifique links antes de acessá-los']]; const scenario=ref(0); const feedback=ref(''); const scenarios=[{text:'URGENTE: sua conta será bloqueada hoje. Confirme seus dados em http://seguranca-conta.exemplo para evitar o cancelamento.',good:false,why:'O endereço é estranho e a mensagem usa urgência para fazer você agir sem pensar.'},{text:'Olá! A atualização mensal está disponível. Abra as configurações do seu dispositivo para conferir.',good:true,why:'A mensagem não pede credenciais nem usa um link encurtado; orienta você a buscar a configuração por conta própria.'}]; function judge(good:boolean){feedback.value=good===scenarios[scenario.value].good?'Boa leitura: essa é a decisão mais segura. ':'Observe com atenção: '+scenarios[scenario.value].why} function next(){scenario.value=(scenario.value+1)%2;feedback.value=''} </script>
<template><div class="page"><div class="container"><div class="eyebrow">Ferramentas práticas</div><h1>Pratique antes<br><span class="brand-accent">de precisar.</span></h1><div class="tools" style="margin-top:38px"><section class="tool-card"><CheckCircle2 color="#1261ee"/><h2>Checklist de segurança</h2><p class="muted">Marque o que já está em dia. O resultado fica salvo somente neste navegador.</p><div class="checklist"><label v-for="item in items" :key="item[0]" class="check-item"><input type="checkbox" :checked="checklist.includes(item[0])" @change="toggleCheck(item[0])"/><span>{{item[1]}}</span></label></div></section><section class="tool-card"><ShieldAlert color="#d58a12"/><h2>Simulador de phishing</h2><p class="muted">Exemplos fictícios. Nenhum dado é enviado ou solicitado.</p><div class="panel" style="margin-top:20px"><small class="muted">MENSAGEM SIMULADA</small><p style="font-size:14px">{{scenarios[scenario].text}}</p><div class="actions"><button class="button secondary" @click="judge(false)">Parece golpe</button><button class="button secondary" @click="judge(true)">Parece seguro</button></div><div v-if="feedback" class="feedback">{{feedback}} <span v-if="feedback.includes('Boa')">{{scenarios[scenario].why}}</span></div><button class="button primary" style="margin-top:18px" @click="next">Próximo exemplo <ExternalLink :size="14"/></button></div></section></div></div></div></template>
